// 列表封面推导：/kanshu/<a>/<b>/ → /files/article/image/<a>/<b>/<b>s.jpg
fn tyCover(u, base) {
  let a = str(match(str(u), '/(\\d+)/(\\d+)/', 1))
  let b = str(match(str(u), '/(\\d+)/(\\d+)/', 2))
  if (a == '' || b == '') { return '' }
  return str(base) + '/files/article/image/' + a + '/' + b + '/' + b + 's.jpg'
}

// 目录并发：站点用 <select> 把全部目录页列成 option，任何一页都列全；
// 把整批地址交给引擎 → 每批 4 页并发，引擎自动跳过已抓过的（含当前页）。
// 单页书只有 1 个 option → 返回空串即停止。option 是相对地址，先转绝对。
fn tyTocPages(s, u) {
  let all = matchAll(str(s), '<option[^>]*value="([^"]*)"', 1)
  if (len(all) < 2) { return '' }
  return map(all, x => absUrl(str(x), str(u)))
}
